    if (!m) return "";
    var id = m[1];
    var p = id.length <= 3 ? "0" : id.slice(0, -3);
    return "https://www.deqixs.cc/files/article/image/" + p + "/" + id + "/" + id + "s.jpg";
}

function words(html) {
    var m = String(html).match(/towan\('(\d+)'\)/);
    if (m) return m[1];
    return String(html).replace(/<[^>]+>/g, "").replace(/字数[：:]/g, "").trim();
}

